from pathlib import Path
from html import escape
import json, shutil
from PIL import Image
from data import CLIENTS, PRODUCTS, MATERIALS, INDUSTRIES
ROOT=Path(__file__).resolve().parents[1]; SITE=ROOT/'site'
(SITE/'assets/img').mkdir(parents=True,exist_ok=True)
shutil.copytree(ROOT/'assets/fonts', SITE/'assets/fonts', dirs_exist_ok=True)
# The original logo is retained in the static assets.
for media in (ROOT/'reference/media').iterdir():
    if media.suffix in ('.jpg', '.mp4'):
        shutil.copy2(media, SITE/'assets/img'/media.name)
photo_alts = ['Machinists drilling a tube sheet', 'White vessel on a flatbed trailer', 'Shell section and painting', 'White and black vessels outdoors', 'Welders at work', 'Crane lift and exchanger on a trailer', 'Tube-to-tubesheet welds']
def photo(n):
    return f'<img src="/assets/img/banner-{n}.jpg" alt="{photo_alts[n]}" width="605" height="120" loading="lazy">'
def photos(*numbers):
    return '<div class="photo-grid">'+''.join(photo(n) for n in numbers)+'</div>'
def gallery():
    return '<div class="photo-grid">'+''.join(f'<a href="/assets/img/banner-{n}.jpg">{photo(n)}</a>' for n in range(7))+'</div>'
def video():
    return '<video controls preload="none" playsinline poster="/assets/img/viper-drilling-poster.jpg" width="520" height="290" aria-label="Viper 2 drilling"><source src="/assets/img/viper-drilling.mp4" type="video/mp4"></video>'
nav=[('Engineering','/engineering-design/'),('Heat exchangers','/heat-exchangers/'),('Waste heat recovery','/waste-heat-recovery/'),('Special products','/special-products/'),('Fabrication','/fabrication/'),('Repairs','/repairs/'),('Facility','/facility/'),('Clients','/clients/'),('Photos','/photos/'),('Contact','/contact/')]
def listitems(items, cls=''): return '<ul class="'+cls+'">'+''.join('<li>'+escape(x)+'</li>' for x in items)+'</ul>'
# Individual scenes are extracted from the original composite banners without upscaling.
scenes = {0:(0,0,204,120), 2:(205,0,605,120), 3:(0,0,267,120), 4:(202,0,400,120), 5:(291,0,605,120), 6:(0,0,200,120), 7:(267,0,605,120)}
for number, box in scenes.items():
    Image.open(ROOT/'reference/media'/f'banner-{3 if number == 7 else number}.jpg').crop(box).save(SITE/'assets/img'/f'scene-{number}.jpg', quality=90)
def scene(n):
    box=scenes[n]
    return f'<img src="/assets/img/scene-{n}.jpg" alt="{photo_alts[3 if n == 7 else n]}" width="{box[2]-box[0]}" height="120" style="max-width:{(box[2]-box[0])*1.5}px" loading="lazy">'
def card(title, url, n): return f'<a class="capability" href="{url}">{scene(n)}<div><h3>{title}</h3></div></a>'
def section(title, body, id=''): return f'<section class="section" {("id="+chr(34)+id+chr(34)) if id else ""}><div class="wrap"><h2>{title}</h2>{body}</div></section>'
def intro(title, text=''): return f'<div class="page-intro"><div class="wrap"><a class="back-link" href="/">Home</a><h1>{title}</h1>{"<p>"+text+"</p>" if text else ""}</div></div>'
def cta(): return '<section class="contact-band"><div class="wrap band-inner"><a class="band-phone" href="tel:+13146313311">(314) 631-3311</a><a class="button light" href="/contact/">Contact us</a></div></section>'
home='<section class="hero"><div class="wrap hero-layout"><div><h1>ASME Code heat transfer equipment</h1><div class="actions"><a class="button" href="/contact/">Contact us</a><a class="text-link" href="/fabrication/">Explore fabrication</a></div></div></div></section>'
home+=section('Products and services','<div class="capabilities">'+card('Heat exchangers','/heat-exchangers/',5)+card('Waste heat recovery','/waste-heat-recovery/',7)+card('Special products','/special-products/',3)+card('Replacements & repairs','/repairs/',2)+'</div>')
home+=section('About','<div class="split"><p class="lead">Heat Transfer Systems, a minority held company, was founded in 1980 to serve the needs of the chemical and petroleum industries.</p><div class="about-copy"><p>With our experienced in-house engineering staff we are able to tackle the challenging needs of our customers while using good design practices and building serviceability into our equipment. Fabrication by skilled craftsmen provides our customers with the assurance that the quality standards expected will be met and exceeded.</p><a class="inline-link" href="/clients/">Clients</a></div></div>')
home+=section('Fabrication','<div class="process"><a href="/fabrication/#cutting"><span>Cutting & material processing</span>'+scene(0)+'</a><a href="/fabrication/#welding"><span>Welding & assembly</span>'+scene(4)+'</a><a href="/fabrication/#testing"><span>Testing & inspection</span>'+scene(6)+'</a></div>')
home+=cta()
pages={
'':('Heat Transfer Systems, Inc.','Custom design and fabrication of ASME Code pressure vessels and heat transfer equipment.',home),
'engineering-design':('Engineering and Design','Thermal and mechanical design and drafting are handled in house.',intro('Engineering and design')+section('In-house engineering','<div class="prose"><p>All engineering functions including thermal and mechanical design and drafting are handled in house utilizing both commercial and proprietary custom software. This allows us to adapt to customer requirements and schedules and reduce the duration of the initial engineering phase before jobs move to production.</p><p>The engineering department draws upon the design and fabrication experience within our company.</p></div>')+cta()),
'heat-exchangers':('Heat Exchangers','Shell and tube heat exchangers, designed and fabricated by Heat Transfer Systems.',intro('Heat exchangers')+section('Design and construction','<div class="split"><p class="lead">Our focus is the custom design and fabrication of ASME Code pressure vessels, specializing in heat transfer equipment.</p><div><p>All engineering functions including thermal and mechanical design and drafting are handled in house utilizing both commercial and proprietary custom software.</p><a class="inline-link" href="/engineering-design/">Engineering and design</a></div></div>')+section('Products',listitems(PRODUCTS,'columns'))+section('Materials of construction',listitems(MATERIALS,'columns'))+section('Construction',listitems(['ASME Section VIII and Section I','TEMA','Customer Specification'],'columns'))+cta()),
'waste-heat-recovery':('Waste Heat Recovery','Waste heat recovery units for gas turbines and other high temperature heat sources.',intro('Waste heat recovery')+section('Heat recovery equipment','<p>Waste heat recovery units for gas turbines and other high temperature heat sources.</p>'+listitems(['Waste Heat Recovery Units','Heat Recovery Boilers','Heat Recovery Systems','Feedwater Heaters'],'columns'))+cta()),
'special-products':('Special Products','Other types of exchangers and pressure vessels designed and fabricated by Heat Transfer Systems.',intro('Special products')+section('Examples','<p class="lead narrow">In addition to shell and tube heat exchangers and waste heat recovery units, Heat Transfer Systems has the capability to design and fabricate other types of exchangers and pressure vessels.</p>'+photos(3)+listitems(['10 foot diameter pressure vessel with internal heating coil','Fluidizer assembly','Alloy 20 and steel double pipe exchanger','Inter-connected electric heaters','Finned tube air cooler','Ultra low vacuum satellite test chamber'],'feature-list'))+cta()),
'fabrication':('Fabrication','Cutting, material processing, welding, assembly, testing and inspection.',intro('Fabrication')+section('Cutting & material processing','<div class="split"><div><p>We stock many materials to minimize delays in fabrication. We typically stock carbon steel plate through 4” thick and 300 series stainless through 2.5” thick. We stock carbon steel pipe through 24” and stainless pipe through 12”.</p><p>Our material processing equipment enables us to process raw material in our own facility, providing closer control on scheduling to customer requirements.</p></div><div><h3>Capabilities</h3>'+listitems(['Press braking and shearing','Plate rolling up to 2.75” t','CNC flame and plasma (regular and high definition) cutting','CNC drilling and machining','2 - Mighty Viper B2000GXT - 83” x 77” both with HP coolant, one with extended 36” Z axis','2 - Quickmill 324” x 120” both with HP coolant','Custom dual 50 HP spindle 540” x 144”'])+'</div></div>'+photos(0)+'<div class="video-row"><p>Deep hole drilling of 15” thick carbon steel tubesheet with 1854 - 0.758” special close fit holes. Almost 20 x Diameter.</p>'+video()+'</div>','cutting')+section('Welding & assembly','<div class="prose"><p>Fabrication at Heat Transfer Systems is performed by skilled craftsmen using modern equipment and fabrication techniques. We have developed welding procedures to meet requirements and are ready to develop more to meet your specific needs.</p><p>Equipment fabricated in our shop ranges from simple carbon steel to complex exotic metals, 300 pound to 300,000 pounds units, and vessels for use at atmospheric pressure to natural gas exchangers rated for 10,000 psi and up.</p></div>'+photos(4,6),'welding')+section('Testing & inspection','<div class="split"><div><p>Full time Quality Control inspection and a comprehensive Quality Control System governed by the ASME and National Board support the quality standards of our customers and our own.</p><p>The inspection of each unit is tracked using a Rider/QC Checklist for all customer, ASME AI, and HTS requirements.</p></div><div><h3>Inspection capabilities</h3>'+listitems(['Hydrotest - 15,000 psi capacity','Visual and dimensional checks','Post machining inspection of tubesheets and baffles','In house NDE – PT, hardness, PMI (Niton XL3T)','Paint and blast inspection','Multiple NDE subcontractors qualified for RT, UT, PT, MT, PMI, halide leak testing, and more'])+'</div></div>'+photos(2),'testing')+cta()),
'repairs':('Replacements and Repairs','Repair Services',intro('Replacements and repairs')+section('Existing equipment','<p class="lead narrow">Heat Transfer Systems offers services in replacement, repair and modification to existing units regardless of who fabricated the original equipment. We realize that down time is costly and stand ready to make your down time as brief as possible.</p>'+photos(2))+cta()),
'facility':('Facility','Heat Transfer Systems facilities survey and manufacturing information.',intro('Facility')+section('Facilities survey','<div class="split"><p class="lead">Complete thermal, mechanical, and drafting services in house.</p><div><a class="button dark" href="/assets/docs/HTS%20Facilities%20Survey.pdf">View facilities survey (PDF)</a></div></div>')+section('Facility information','<div class="split"><div><h3>Manufacturing</h3>'+listitems(['75,000 square feet under roof','2.5 acres yard storage','All bays serviced by overhead bridge cranes','Heavy duty rail system for movement between bays'])+'</div><div><h3>Solar array</h3><p>Since December 2013, the facilities have had a 175kW roof-mounted solar array consisting of 673 260-watt panels made in the USA.</p></div></div>')+cta()),
'clients':('Clients Served','Clients served by Heat Transfer Systems throughout the world.',intro('Clients served')+'<section class="section"><div class="wrap">'+listitems(CLIENTS,'columns clients')+'</div></section>'+section('Industries served',listitems(INDUSTRIES,'columns'))+cta()),
'photos':('Photo Gallery','Heat Transfer Systems photo gallery.',intro('Photos')+'<section class="section"><div class="wrap">'+gallery()+'<p>To browse photo sets and descriptions, see our <a class="inline-link" href="https://www.flickr.com/photos/heattransfersys/sets/">Flickr page</a>.</p></div></section>'+cta()),
'contact':('Contact','Contact Heat Transfer Systems in St. Louis, Missouri.',intro('Contact')+section('Get in touch','<div class="contact-grid"><div><h3>Heat Transfer Systems, Inc.</h3><address>8100 Polk Street<br>St. Louis, MO 63111</address><p><a href="tel:+13146313311">(314) 631-3311</a><br>Fax: (314) 631-3399<br><a href="mailto:andrew.kwong@heattransfersys.com">andrew.kwong@heattransfersys.com</a></p></div><form id="contact-form"><!-- Replace the mailto fallback with a production form endpoint here. --><label for="name">Name</label><input id="name" name="Name" autocomplete="name" required><label for="email">Email</label><input id="email" name="Email" type="email" autocomplete="email" required><label for="phone">Phone</label><input id="phone" name="Phone" type="tel" autocomplete="tel"><label for="message">Message</label><textarea id="message" name="Message" rows="6" required></textarea><button class="button dark" type="submit">Send inquiry</button><p id="form-status" role="status"></p></form></div>'))}
org={"@context":"https://schema.org","@type":"Organization","name":"Heat Transfer Systems, Inc.","url":"https://heattransfersys.com/","telephone":"+1-314-631-3311","faxNumber":"+1-314-631-3399","email":"andrew.kwong@heattransfersys.com","address":{"@type":"PostalAddress","streetAddress":"8100 Polk Street","addressLocality":"St. Louis","addressRegion":"MO","postalCode":"63111"}}
for slug,(title,desc,body) in pages.items():
    def navlink(label, url):
        return f'<a href="{url}"'+(' aria-current="page"' if url==('/'+slug+'/' if slug else '/') else '')+f'>{label}</a>'
    links=''.join('<li>'+navlink(label,url)+'</li>' for label,url in nav)
    groups=[('Equipment',nav[1:4]),('Capabilities',[nav[0],nav[4],nav[5]]),('Company',nav[6:])]
    menu=''.join('<li><span>'+name+'</span><ul>'+''.join('<li>'+navlink(label,url)+'</li>' for label,url in group)+'</ul></li>' for name,group in groups)
    primary=[nav[0],nav[4],nav[5],nav[6],nav[7],nav[8]]
    products='<li class="product-menu"><details><summary>Products</summary><ul>'+''.join('<li>'+navlink(label,url)+'</li>' for label,url in nav[1:4])+'</ul></details></li>'
    primary_links=products+''.join('<li>'+navlink(label,url)+'</li>' for label,url in primary)
    related = next((group for name,group in groups if any(url == '/'+slug+'/' for _,url in group)), []) if slug else []
    siblings = '<nav class="siblings" aria-label="Related pages"><ul>'+''.join('<li>'+navlink(label,url)+'</li>' for label,url in related)+'</ul></nav>' if related else ''
    body=body.replace('</h1>', '</h1>'+siblings, 1)
    html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex"><title>{escape(title)} | Heat Transfer Systems</title><meta name="description" content="{escape(desc)}"><meta property="og:title" content="{escape(title)} | Heat Transfer Systems"><meta property="og:description" content="{escape(desc)}"><meta property="og:type" content="website"><meta property="og:url" content="https://heattransfersys.com/{slug+'/' if slug else ''}"><link rel="icon" href="/assets/img/hts-symbol.png" type="image/png"><link rel="preload" href="/assets/fonts/chivo-800.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="/assets/css/site.css"><script type="application/ld+json">{json.dumps(org)}</script><script defer src="/assets/js/site.js"></script></head><body><a class="skip" href="#main">Skip to content</a><header class="site-header{ ' home-header' if not slug else '' }"><div class="wrap header-inner"><a class="brand" href="/"><img src="/assets/img/hts-logo-real.png" width="216" height="240" alt="Heat Transfer Systems"></a><div class="header-right"><nav class="primary-nav" aria-label="Primary navigation"><ul>{primary_links}</ul></nav><a class="header-phone" href="tel:+13146313311">(314) 631-3311</a><a class="header-contact" href="/contact/">Contact</a><button class="menu-toggle" aria-expanded="false" aria-controls="navigation">Menu</button><nav id="navigation" aria-label="Main navigation"><ul class="menu-groups">{menu}</ul></nav></div></div></header><main id="main">{body}</main><footer><div class="wrap footer-grid"><div><a class="footer-brand" href="/"><img src="/assets/img/hts-logo-real.png" width="216" height="240" alt="Heat Transfer Systems"></a><p>8100 Polk Street<br>St. Louis, MO 63111</p><p><a href="tel:+13146313311">(314) 631-3311</a><br><a href="mailto:andrew.kwong@heattransfersys.com">andrew.kwong@heattransfersys.com</a></p></div><ul class="footer-links">{links}</ul></div></footer></body></html>'''
    html=html.replace('</a><a', '</a> <a').replace('</a><button', '</a> <button')
    dest=SITE/slug/'index.html'; dest.parent.mkdir(parents=True,exist_ok=True); dest.write_text(html)
(SITE/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>https://heattransfersys.com/'+(s+'/' if s else '')+'</loc></url>' for s in pages)+'</urlset>')
# Keep the error page in the generated output, using the same shared shell.
s=(SITE/'index.html').read_text(); start=s.index('<main id="main">'); end=s.index('</main>',start)
s=s[:start]+'<main id="main"><div class="page-intro"><div class="wrap"><h1>Page not found</h1><p>The page you requested could not be found.</p></div></div><section class="section"><div class="wrap"><a class="button dark" href="/">Return home</a></div></section>'+s[end:]
s=s.replace('site-header home-header', 'site-header')
s=s.replace('<title>Heat Transfer Systems, Inc. | Heat Transfer Systems</title>','<title>Page not found | Heat Transfer Systems</title>')
(SITE/'404.html').write_text(s)
